const tunda = (ms, nilai) => new Promise((r) => setTimeout(() => r(nilai), ms));
const urutan = [];
async function ambil(nama, ms) {
  await tunda(ms);
  urutan.push(nama);
  return nama.toUpperCase();
}
const hasil = await Promise.all([ambil('kopi', 30), ambil('teh', 10), ambil('roti', 20)]);
console.log(hasil);
console.log(urutan);
const status = await Promise.allSettled([tunda(5, 'ok'), Promise.reject(new Error('habis'))]);
console.log(status.map((s) => s.status));
console.log(await Promise.race([tunda(30, 'lambat'), tunda(10, 'cepat')]));

