  if (menu === 'Es Krim') throw new Error('Es Krim habis');
  return `${menu} siap`;
}
console.log(await masak('Kopi'));
console.log(await masak('Teh'));
console.log(await masak('Roti'));
const semua = await Promise.all(['Kopi', 'Teh', 'Roti'].map((m) => masak(m)));
console.log(semua.join(', '));
const status = await Promise.allSettled(['Kopi', 'Es Krim'].map((m) => masak(m)));
console.log(status.map((s) => s.status).join(', '));

