const daftar = { 1: 10000, 2: 20000, 3: 30000 };
const harga = (id) => new Promise((r) => setTimeout(() => r(daftar[id]), 10));
const semua = await Promise.all([1, 2, 3].map((id) => harga(id)));
console.log('Total:', semua.reduce((a, b) => a + b, 0));
